<script setup>
import { assetUrl } from '../assets.js';
import { ref } from 'vue';
import { WandSparkles, Sparkles, ArrowRight, Bookmark, Download, ExternalLink, Orbit } from '@lucide/vue';
import { createKnowledgeCard } from '../knowledge.js';
defineEmits(['save']);
const topic=ref('木星大红斑'),level=ref('入门'),card=ref(null),busy=ref(false),error=ref('');
let timer;
import { onUnmounted } from 'vue';
onUnmounted(()=>clearTimeout(timer));
function generate(){if(!topic.value.trim()||busy.value)return;busy.value=true;error.value='';timer=setTimeout(()=>{card.value=createKnowledgeCard(topic.value,level.value);if(!card.value)error.value='离线资料库暂未覆盖这个主题。试试“土星”“木星大红斑”“太阳”或“仙女座”。';busy.value=false},650)}
function exportCard(){const c=card.value;const content=`# ${c.title}\n\n${c.intro}\n\n${c.points.map(p=>'- '+p).join('\n')}\n\n冷知识：${c.fact}\n\n来源：${c.source}\n\n星语知识卡 · 本地资料演示`;const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`星语知识卡-${c.id}.md`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template>
  <section class="page-shell"><div class="eyebrow">TURN YOUR CURIOSITY INTO A KEEPSAKE</div><h1>知识卡工作室<span class="heading-dot">.</span></h1><p class="page-description">一个小问题，一张装得下宇宙的知识卡。</p><div class="studio-layout"><div class="studio-form"><div class="studio-title"><WandSparkles :size="24"/><h2>今天，想了解什么？</h2></div><span class="demo-pill">本地资料演示 · 未接入 AI 生成</span><form @submit.prevent="generate"><label for="card-topic">探索主题</label><input id="card-topic" v-model="topic" maxlength="100" placeholder="例如：木星大红斑"/><div class="suggestion-row"><button v-for="name in ['木星大红斑','土星光环','仙女座星系','太阳']" type="button" @click="topic=name">{{name}}</button></div><label for="card-level">阅读深度</label><select id="card-level" v-model="level"><option>入门</option><option>进阶</option></select><p class="small-note">入门：简洁概述 · 进阶：增加背景原理。<br/>知识卡依据本地资料重新编排，附上原始来源。</p><button type="submit" class="button primary" :disabled="busy||!topic.trim()"><Sparkles :size="17"/>{{busy?'正在整理知识…':'制作我的知识卡'}} </button><p v-if="error" class="form-error" role="alert">{{error}}</p></form></div><div class="studio-preview" :aria-busy="busy"><article v-if="card" class="generated-card"><img :src="assetUrl(`/images/${card.image}.jpg`)" :alt="card.title"/><div class="generated-content"><div class="eyebrow">STARWHISPER KNOWLEDGE CARD · {{card.level}}</div><h2>{{card.title}}</h2><p>{{card.intro}}</p><ol><li v-for="point in card.points">{{point}}</li></ol><div class="mini-fact"><Sparkles :size="17"/><span>{{card.fact}}</span></div><a class="source-link" :href="card.source" target="_blank" rel="noopener noreferrer">{{card.sourceName}} </a><div class="detail-actions"><button class="button primary" @click="$emit('save',card)"><Bookmark :size="16"/> 收藏知识卡</button><button class="button secondary" @click="exportCard"><Download :size="16"/> 导出 Markdown</button></div></div></article><div v-else class="studio-empty"><div class="preview-outline"><Orbit :size="60" :stroke-width="1"/><span>YOUR UNIVERSE,<br/>IN A CARD.</span><i></i><i></i><i></i></div><p>你的第一张宇宙知识卡，<br/>即将在这里诞生。</p></div></div></div></section>
</template>
